uv run python -c 'import sys,tempfile; from pathlib import Path; sys.path[:0]=["tests"]; import test_trust_mutants as T; r=Path(tempfile.mkdtemp())/"p"; T.scaffold(r,""); (r/"lean/lakefile.toml").write_text("name = \"demo\"\n\n[[lean_lib]]\nname = \"Demo\"\nroots = [\"Demo.Defs\"]\n\n[lean_lib.leanOptions]\nsynthInstance.maxSize = 512\n"); (r/"lean/Demo/Defs.lean").write_text("namespace Demo\n\nclass Deep (n : Nat) where\n  val : Nat\n\ninstance : Deep 0 := ⟨0⟩\n\ninstance [s : Deep n] : Deep (n + 1) := ⟨s.val + 1⟩\n\ndef fastSmall (n : Nat) : Bool := n < 3\n\ntheorem fastSmall_iff (n : Nat) : fastSmall n = true ↔ n < 3 := by\n  simp [fastSmall]\n\ndef Small (n : Nat) : Prop := n < 3\n\ninstance (priority := low) slowSmall (n : Nat) : Decidable (Small n) := Nat.decLt n 3\n\ninstance fastSmallDec (n : Nat) [Deep 130] : Decidable (Small n) := decidable_of_iff _ (fastSmall_iff n)\n\n#guard fastSmall 7 == fastSmall 7 && decide (Small 2)\n\nend Demo\n"); T.dump(r,Path(tempfile.mkdtemp()),[]); T.git(r,"add","."); T.git(r,"commit","-qm","head"); s=[(m["operator"],m["status"],m["detail"][:90]) for m in T.of(T.tool(r,r.parent/"run")[1],"fastSmall")]; print(s); assert s and not any(x=="KILLED" for _,x,_ in s), s'
